import{_ as n,o as i,c as t,a2 as a}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"ApptiveTeams — Tipps und Fehlerbehebung","description":"Warum Teams, Tabs, Kacheln oder das Branding in der App nicht erscheinen.","frontmatter":{"title":"ApptiveTeams — Tipps und Fehlerbehebung","description":"Warum Teams, Tabs, Kacheln oder das Branding in der App nicht erscheinen."},"headers":[],"relativePath":"apptiveteams/fehlerbehebung.md","filePath":"apptiveteams/fehlerbehebung.md","lastUpdated":1786357627000}'),r={name:"apptiveteams/fehlerbehebung.md"};function d(l,e,h,s,o,c){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="tipps-und-fehlerbehebung" tabindex="-1">Tipps und Fehlerbehebung <a class="header-anchor" href="#tipps-und-fehlerbehebung" aria-label="Permalink to &quot;Tipps und Fehlerbehebung&quot;">​</a></h1><p>ApptiveTeams meldet Konfigurationsfehler nicht, sondern lässt Fehlerhaftes <strong>weg</strong>. Ein fehlender Tab ist deshalb fast immer ein Keys- oder Pflichtfeld-Problem.</p><h2 id="die-app-zeigt-kein-team-an" tabindex="-1">Die App zeigt kein Team an <a class="header-anchor" href="#die-app-zeigt-kein-team-an" aria-label="Permalink to &quot;Die App zeigt kein Team an&quot;">​</a></h2><p>Zwei Ursachen kommen in Frage:</p><ol><li>Der Space hat nicht die Kategorie <code>apptiveTeams</code>. → <a href="/apptiveteams/team-space">Team Space einrichten</a></li><li>Die angemeldete Person ist nicht Mitglied des Space. → <a href="/zusammenarbeit/personen-einladen">Personen einladen</a></li></ol><h2 id="die-untere-tab-leiste-erscheint-nicht" tabindex="-1">Die untere Tab-Leiste erscheint nicht <a class="header-anchor" href="#die-untere-tab-leiste-erscheint-nicht" aria-label="Permalink to &quot;Die untere Tab-Leiste erscheint nicht&quot;">​</a></h2><p>Die Navigationsleiste wird erst ab <strong>zwei gültigen Tabs</strong> angezeigt. Prüfen Sie, ob mindestens zwei Zeilen im <code>tabs</code>-Grid alle Pflichtfelder gefüllt haben — eine Zeile mit fehlendem Icon zählt nicht mit.</p><h2 id="ein-tab-eine-kachel-oder-eine-karte-fehlt" tabindex="-1">Ein Tab, eine Kachel oder eine Karte fehlt <a class="header-anchor" href="#ein-tab-eine-kachel-oder-eine-karte-fehlt" aria-label="Permalink to &quot;Ein Tab, eine Kachel oder eine Karte fehlt&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prüfen Sie</th><th>Warum</th></tr></thead><tbody><tr><td>Alle Pflichtfelder gefüllt?</td><td>Zeilen mit Lücken werden übersprungen</td></tr><tr><td>Feld-Keys exakt geschrieben?</td><td>Groß- und Kleinschreibung zählt</td></tr><tr><td>Bei Tabs: <code>type</code> korrekt?</td><td>Nur <code>TilesGrid</code>, <code>CardList</code> und <code>WebView</code> sind gültig</td></tr><tr><td>Bei Kacheln/Karten: <code>actionType</code> korrekt?</td><td>Ein unbekannter Wert macht die Zeile unbrauchbar</td></tr><tr><td>Ist eine gefilterte Ansicht verknüpft?</td><td>Dann kann der Filter die Zeile ausblenden</td></tr></tbody></table><h2 id="logo-oder-farbe-werden-nicht-ubernommen" tabindex="-1">Logo oder Farbe werden nicht übernommen <a class="header-anchor" href="#logo-oder-farbe-werden-nicht-ubernommen" aria-label="Permalink to &quot;Logo oder Farbe werden nicht übernommen&quot;">​</a></h2><p>Im <code>config</code>-Grid müssen <code>logo</code> <strong>und</strong> <code>primaryColor</code> gefüllt sein — fehlt eines, wird die ganze Zeile ignoriert und die App startet ohne jedes Branding.</p><p>Die Farbe muss ein Hex-Wert wie <code>#1565C0</code> sein. Beachten Sie außerdem, dass nur die <strong>erste Zeile</strong> des Grids ausgewertet wird.</p><h2 id="icons-werden-nicht-angezeigt" tabindex="-1">Icons werden nicht angezeigt <a class="header-anchor" href="#icons-werden-nicht-angezeigt" aria-label="Permalink to &quot;Icons werden nicht angezeigt&quot;">​</a></h2><p>Tab- und Kachel-Icons müssen <strong>SVG-Dateien</strong> sein — ein PNG oder JPG wird nicht dargestellt. Da die App die Icons einfärbt, funktionieren einfarbige SVGs ohne eigene Farbflächen am besten.</p><h2 id="ein-webview-tab-bleibt-leer" tabindex="-1">Ein WebView-Tab bleibt leer <a class="header-anchor" href="#ein-webview-tab-bleibt-leer" aria-label="Permalink to &quot;Ein WebView-Tab bleibt leer&quot;">​</a></h2><p>Manche Websites verbieten die Anzeige in eingebetteten Ansichten. Öffnen Sie die Adresse zum Vergleich im Browser des Geräts. Lässt sie sich dort öffnen, aber nicht in der App, ist die Einbettung durch die Zielseite blockiert — dann bleibt nur eine Kachel mit <code>externalLink</code>.</p><h2 id="anderungen-erscheinen-nicht-in-der-app" tabindex="-1">Änderungen erscheinen nicht in der App <a class="header-anchor" href="#anderungen-erscheinen-nicht-in-der-app" aria-label="Permalink to &quot;Änderungen erscheinen nicht in der App&quot;">​</a></h2><p>Tippen Sie auf das <strong>Aktualisieren-Symbol</strong> oben rechts oder starten Sie die App neu. Die Konfiguration wird nicht laufend nachgeladen.</p><h2 id="„erstellt-von-zeigt-nicht-die-richtige-person" tabindex="-1">„Erstellt von&quot; zeigt nicht die richtige Person <a class="header-anchor" href="#„erstellt-von-zeigt-nicht-die-richtige-person" aria-label="Permalink to &quot;„Erstellt von&quot; zeigt nicht die richtige Person&quot;">​</a></h2><p>Die Kachel oder Karte verwendet vermutlich <code>externalLink</code>. Nur <code>internalLink</code> übergibt die angemeldete Person an das Formular. → <a href="/apptiveteams/kacheln-und-karten#aktionstypen">Kacheln und Karten</a></p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/apptiveteams/team-space">Team Space einrichten</a></li><li><a href="/apptiveteams/tabs">Tabs einrichten</a></li><li><a href="/fehlerbehebung/haeufige-fehlermeldungen">Häufige Fehlermeldungen</a></li></ul>',22)])])}const u=n(r,[["render",d]]);export{p as __pageData,u as default};
